import random

# カードの配列を用意
cards = [1, 2, 3, 4, 5, 6]

def main():
    # カードの配列をシャッフル
    random.shuffle(cards)

    input_count = 0
    index = 0

    while True:
        print("1枚目のカードを選んでください。")
        A = int(input()) - 1  # 0から始まるインデックスに変換
        if A < 0 or A >= len(cards):
            print("無効な入力です。ゲームを終了します。")
            return

        # 机の状態を表示
        display_board(index, cards)

        if index == A:
            print("2枚目のカードを選んでください。")
            B = int(input()) - 1  # 0から始まるインデックスに変換
            if B < 0 or B >= len(cards):
                print("無効な入力です。ゲームを終了します。")
                return

            # 机の状態を表示
            display_board(index, cards)

            if A == B:
                print("入力間違いです。続けてください。")
                input_count += 1
            else:
                if check_correct(A, B, cards):
                    print("正解です！ゲームクリアです。")
                    return
                else:
                    print("残念ながら不正解です。続けてください。")
                    input_count += 1
        else:
            break

    # 入力回数と机の状態を出力
    print(f"入力回数: {input_count}")
    display_board(index, cards)

def display_board(index, cards):
    board = []
    for i in range(len(cards)):
        if i == index:
            board.append("0")
        elif i == A or i == B:
            board.append(f"[{cards[i]}]")
        elif cards[i] == 0:
            board.append("👌")
        else:
            board.append("■")
    print(board)

def check_correct(A, B, cards):
    if cards[A] == cards[B]:
        cards[A] = 0
        return True
    return False

if __name__ == "__main__":
    main()
